from __future__ import annotations

from abc import ABC, abstractmethod
from typing import Any, Callable


class DataProcessor(ABC):
    @abstractmethod
    def process(self, data: list[Any]) -> list[Any]:
        pass


class PassthroughProcessor(DataProcessor):
    def process(self, data: list[Any]) -> list[Any]:
        return list(data)


class FilterProcessor(DataProcessor):
    def __init__(self, predicate: Callable[[Any], bool]) -> None:
        self.predicate = predicate

    def process(self, data: list[Any]) -> list[Any]:
        return [item for item in data if self.predicate(item)]


class TransformProcessor(DataProcessor):
    _MISSING = object()

    def __init__(self, transform_fn: Callable[[Any], Any]) -> None:
        self.transform_fn = transform_fn
        self._cache: dict[Any, Any] = {}

    def process(self, data: list[Any]) -> list[Any]:
        return [self._cached_transform(item) for item in data]

    def _cached_transform(self, item: Any) -> Any:
        try:
            cached = self._cache.get(item, self._MISSING)
            if cached is not self._MISSING:
                return cached
            result = self.transform_fn(item)
            self._cache[item] = result
            return result
        except TypeError:
            return self.transform_fn(item)

    def clear_cache(self) -> None:
        self._cache.clear()


class FilterTransformProcessor(DataProcessor):
    _MISSING = object()

    def __init__(self, predicate: Callable[[Any], bool], transform_fn: Callable[[Any], Any]) -> None:
        self.predicate = predicate
        self.transform_fn = transform_fn
        self._cache: dict[Any, Any] = {}

    def process(self, data: list[Any]) -> list[Any]:
        return [self._cached_transform(item) for item in data if self.predicate(item)]

    def _cached_transform(self, item: Any) -> Any:
        try:
            cached = self._cache.get(item, self._MISSING)
            if cached is not self._MISSING:
                return cached
            result = self.transform_fn(item)
            self._cache[item] = result
            return result
        except TypeError:
            return self.transform_fn(item)

    def clear_cache(self) -> None:
        self._cache.clear()


class DataProcessorFactory:
    @staticmethod
    def create(config: dict[str, Any]) -> DataProcessor:
        has_filter = bool(config.get("filter"))
        has_transform = bool(config.get("transform"))

        if has_filter and has_transform:
            return FilterTransformProcessor(config["filter"], config["transform"])
        if has_filter:
            return FilterProcessor(config["filter"])
        if has_transform:
            return TransformProcessor(config["transform"])
        return PassthroughProcessor()

